import { useMemo, useState } from 'react';
import { JxButton, JxDrawer, JxMenu } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

export interface NavigationMenuProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavigationMenu({ onNavigate }: NavigationMenuProps) {
  const [open, setOpen] = useState(false);

  const items = useMemo(() => {
    const select = (key: NavKey) => () => {
      setOpen(false);
      onNavigate(key);
    };

    return [
      { label: 'Проекты', onSelect: select('projects') },
      { label: 'Команда', onSelect: select('team') },
      { label: 'Настройки', onSelect: select('settings') },
      { type: 'divider' as const },
      { label: 'Выйти', danger: true, onSelect: select('logout') },
    ];
  }, [onNavigate]);

  return (
    <>
      <JxButton variant="ghost" onClick={() => setOpen(true)}>
        Меню
      </JxButton>
      <JxDrawer open={open} onOpenChange={setOpen} side="left" title="Меню">
        <JxMenu items={items} />
      </JxDrawer>
    </>
  );
}

